import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        r = float(data)
    except:
        print("Error")
        return
    if r < 0:
        print("Error")
    else:
        c = 2 * (22 / 7) * r
        # Format to 2 decimal places
        print(f"{c:.2f}")

if __name__ == "__main__":
    main()
